def verify(edges, num_vertices=30):
    adj = [set() for _ in range(num_vertices)]
    for u, v in edges:
        assert 0 <= u < v < num_vertices
        adj[u].add(v)
        adj[v].add(u)

    # Check bipartite
    color = [-1] * num_vertices
    for i in range(num_vertices):
        if color[i] == -1:
            color[i] = 0
            q = [i]
            for u in q:
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        q.append(v)
                    elif color[v] == color[u]:
                        return False, "Not bipartite"

    # Check girth >= 7
    # BFS from each vertex to find shortest cycle
    for s in range(num_vertices):
        dist = [-1] * num_vertices
        parent = [-1] * num_vertices
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    # length = dist[u] + dist[v] + 1
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return False, f"Cycle length {cycle_len} found starting from {s}"
    return True, "OK"

